<script>
const csrf=<?=json_encode(csrfToken(),JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;const chat=document.querySelector('#chat');const input=document.querySelector('#question');const errorBox=document.querySelector('#chatError');
function bubble(text,cls){const b=document.createElement('div');b.className='bubble '+cls;b.textContent=text;chat.append(b);b.scrollIntoView({block:'nearest',behavior:'smooth'});return b}
document.querySelectorAll('[data-example]').forEach(btn=>btn.addEventListener('click',()=>{input.value=btn.dataset.example;input.focus()}));
document.querySelector('#askForm').addEventListener('submit',async event=>{event.preventDefault();const q=input.value.trim();if(q.length<3){errorBox.textContent='Typ alstublieft uw vraag.';errorBox.classList.remove('hidden');input.focus();return}errorBox.classList.add('hidden');bubble(q,'you');input.value='';const waiting=bubble('Ik zoek in de bewonersinformatie…','bot');try{const response=await fetch('bewonersportaal_api.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-Token':csrf},body:new URLSearchParams({question:q})});const data=await response.json();waiting.remove();if(!response.ok||!data.ok)throw new Error(data.error||'Uw vraag kon niet worden beantwoord.');const answer=document.createElement('div');answer.className='bubble bot';const strong=document.createElement('strong');strong.textContent='Bewonersassistent';answer.append(strong,document.createTextNode(data.answer));for(const doc of (data.documents||[])){const link=document.createElement('a');link.className='doc-link';link.href='resident_document.php?id='+encodeURIComponent(doc.id);link.textContent='📄 '+doc.title;answer.append(link)}chat.append(answer);answer.scrollIntoView({block:'nearest',behavior:'smooth'})}catch(error){waiting.remove();errorBox.textContent=error.message;errorBox.classList.remove('hidden')}});
</script></body></html>
